from .conftest import event_by_title

ESCAPE_ROOM = "Escape Room: The Locked Lab"   # seeded with 39 of 40 places taken
WORKSHOP = "Maker Workshop: Solder Your Own Badge"  # seeded full


def test_lists_the_festival_programme(client):
    events = client.get("/api/events").json()
    assert len(events) == 5
    assert {"title", "venue", "starts_at", "capacity", "reserved", "places_left"} <= events[0].keys()


def test_reserving_a_place_returns_the_reservation(client):
    event = event_by_title(client, ESCAPE_ROOM)
    res = client.post(f"/api/events/{event['id']}/reservations", json={"attendee": "Maya"})
    assert res.status_code == 201
    assert res.json()["attendee"] == "Maya"
    assert res.json()["event_id"] == event["id"]


def test_a_reservation_uses_up_a_place(client):
    event = event_by_title(client, ESCAPE_ROOM)
    client.post(f"/api/events/{event['id']}/reservations", json={"attendee": "Maya"})
    after = client.get(f"/api/events/{event['id']}").json()
    assert after["reserved"] == 40
    assert after["places_left"] == 0


def test_a_full_event_turns_people_away(client):
    event = event_by_title(client, WORKSHOP)
    res = client.post(f"/api/events/{event['id']}/reservations", json={"attendee": "Sam"})
    assert res.status_code == 409


def test_the_last_place_goes_to_whoever_asks_first(client):
    event = event_by_title(client, ESCAPE_ROOM)
    first = client.post(f"/api/events/{event['id']}/reservations", json={"attendee": "Maya"})
    second = client.post(f"/api/events/{event['id']}/reservations", json={"attendee": "Sam"})
    assert first.status_code == 201
    assert second.status_code == 409
    assert client.get(f"/api/events/{event['id']}").json()["reserved"] == 40


def test_unknown_event_is_404(client):
    res = client.post("/api/events/9999/reservations", json={"attendee": "Maya"})
    assert res.status_code == 404


def test_a_name_is_required(client):
    event = event_by_title(client, ESCAPE_ROOM)
    res = client.post(f"/api/events/{event['id']}/reservations", json={"attendee": ""})
    assert res.status_code == 422

from app import reservations

from .conftest import event_by_title
from .helpers import at_the_same_time, hold_everyone_at_payment

ESCAPE_ROOM = "Escape Room: The Locked Lab"   # seeded with 39 of 40 places taken


def test_the_last_place_goes_to_exactly_one_of_two_people_pressing_at_once(client, monkeypatch):
    event = event_by_title(client, ESCAPE_ROOM)
    hold_everyone_at_payment(monkeypatch, people=2)

    outcomes = at_the_same_time(lambda name: reservations.reserve(event["id"], name), ["Maya", "Sam"])

    winners = [name for name, result in outcomes.items() if isinstance(result, dict)]
    turned_away = [name for name, result in outcomes.items() if isinstance(result, reservations.SoldOut)]
    assert len(winners) == 1, outcomes
    assert len(turned_away) == 1, outcomes
    assert client.get(f"/api/events/{event['id']}").json()["reserved"] == 40
"""Helpers for testing what happens when people act at the same time.

You don't need to understand threads to use these. Two ideas:

  hold_everyone_at_payment(monkeypatch)
      Replaces the payment step so that each request waits there until the others
      arrive (or 2 seconds pass). This makes the unlucky timing from Lecture 1 happen
      every time: everybody checks the count before anybody saves.

  at_the_same_time(action, names)
      Runs action(name) for every name, all starting together, and returns what
      happened to each person: the value action returned, or the exception it raised.
"""

import threading

from app import payments


def hold_everyone_at_payment(monkeypatch, people: int = 2, timeout: float = 2.0) -> None:
    gate = threading.Barrier(people)

    def authorize(attendee: str) -> None:
        try:
            gate.wait(timeout=timeout)
        except threading.BrokenBarrierError:
            pass  # the others could not get here (for example, they are waiting for a lock)

    monkeypatch.setattr(payments, "authorize", authorize)


def at_the_same_time(action, names: list[str]) -> dict:
    start_line = threading.Barrier(len(names))
    outcomes = {}

    def run(name):
        start_line.wait()
        try:
            outcomes[name] = action(name)
        except Exception as exc:
            outcomes[name] = exc

    threads = [threading.Thread(target=run, args=(name,)) for name in names]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)
    return {name: outcomes.get(name, TimeoutError("no answer within 30 s")) for name in names}
# AfterHours — starter

The running project for *Build It. Prove It. Own It.* A small platform for a student-run
campus festival: browse events, reserve one of a limited number of places.

It looks finished. The page is polished and every test passes. Lecture 1 is about why that
is not the same as "it works".

## Set up (once)

You need Python 3.11 or newer.

```bash
python -m venv .venv
source .venv/bin/activate          # Windows: .venv\Scripts\activate
pip install -r requirements.txt
```

## Run it

```bash
uvicorn app.main:app
```

Open http://127.0.0.1:8000, type a name, and reserve a place. The escape room starts with
**one place left**.

The app creates `afterhours.db` next to where you run it. Delete that file to start over
with fresh seed data.

## Test it

```bash
python -m pytest -q
```

## Race it

With the app running in one terminal, run this in a second one:

```bash
python scripts/race.py
```

It creates events with one place, has Maya and Sam press "Reserve" at the same instant,
and checks the promise *confirmed reservations ≤ capacity*. Try `--trials 30`,
`--people Maya,Sam,Lee`, or `--capacity 2`.

Watch the first terminal while it runs. The app logs each step of each reservation with a
millisecond timestamp, which is enough to draw the timeline of what happened.

`python scripts/rush.py` asks a different question: when 20 people book 20 *different*
events at once, how long do they wait, and does everyone get a place?

To test concurrency inside pytest, use `tests/helpers.py` (see its docstring).

## Settings (environment variables)

| Variable | Default | What it does |
|---|---|---|
| `AFTERHOURS_DB` | `afterhours.db` | Path to the SQLite file |
| `AFTERHOURS_PAYMENT_DELAY` | `0.3` | Seconds the simulated payment check takes. Nothing is ever charged |
| `AFTERHOURS_CLASSROOM_GATE` | `0` | Set to `2` for live demos: the first request waits (up to 3 s) at the payment step for a second one, so the two always overlap |

## Map

```
app/
  main.py           HTTP routes
  reservations.py   the reservation rule
  db.py             connections, schema, seed data
  payments.py       payment simulation
  schema.sql        tables
  static/index.html the web page
tests/              the (green) test suite, plus helpers.py for concurrency tests
scripts/race.py     the concurrency check: does the last place go to one person?
scripts/rush.py     the load check: do many people at once all get an answer?
AGENTS.md           instructions for coding agents and new teammates
.github/workflows/  CI: runs the tests on every push
```
