<script>
const eventsEl = document.getElementById("events");
const toastEl = document.getElementById("toast");

function when(iso) {
  const d = new Date(iso);
  return d.toLocaleString(undefined, { weekday: "short", hour: "2-digit", minute: "2-digit" });
}

function toast(text, bad = false) {
  toastEl.textContent = text;
  toastEl.className = bad ? "bad" : "";
  toastEl.hidden = false;
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => (toastEl.hidden = true), 3500);
}

async function load() {
  const events = await (await fetch("/api/events")).json();
  eventsEl.replaceChildren(...events.map(render));
}

function render(ev) {
  const card = document.createElement("article");
  card.className = "event";
  const left = ev.places_left;
  const leftText = left <= 0 ? "Full" : left === 1 ? "1 place left!" : `${left} places left`;
  const leftClass = left <= 0 ? "none" : left === 1 ? "last" : "";
  const pct = Math.min(100, Math.round((ev.reserved / ev.capacity) * 100));
  card.innerHTML = `
    <h2></h2>
    <div class="meta"></div>
    <div class="left ${leftClass}">${leftText}</div>
    <div class="meter" aria-hidden="true"><i style="width:${pct}%"></i></div>
    <button type="button">Reserve</button>`;
  card.querySelector("h2").textContent = ev.title;
  card.querySelector(".meta").textContent = `${when(ev.starts_at)} · ${ev.venue}`;
  const button = card.querySelector("button");
  button.disabled = left <= 0;
  button.addEventListener("click", () => reserve(ev, button));
  return card;
}

async function reserve(ev, button) {
  const attendee = document.getElementById("attendee").value.trim();
  if (!attendee) {
    toast("Type your name first, then press Reserve.", true);
    document.getElementById("attendee").focus();
    return;
  }
  const res = await fetch(`/api/events/${ev.id}/reservations`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ attendee }),
  });
  if (res.status === 201) {
    const r = await res.json();
    toast(`You're in! Reservation #${r.id} for ${ev.title}.`);
  } else if (res.status === 409) {
    toast("Sorry, that event just filled up.", true);
  } else {
    toast("Something went wrong. Please try again.", true);
  }
  await load();
}

load();
</script>
